#[derive(Debug, Clone)]
pub struct CompleteArgs {
}

pub fn dispatch_complete(
    repo: &mut impl crate::kernel::Repository<Contract>, id: &str, args: CompleteArgs, mutations: &mut Vec<crate::kernel::MutationRecord>,
) -> crate::kernel::DispatchResult<Contract> {


    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Complete",
        "Embryonaut::Contract",
        "Contract",
        "number.value",
        &args,
        &[

        ],
        Some(crate::kernel::TransitionCheck { field: "status", from_states: &["active"] }),
        |record| {
        record.status = "completed".to_string();
            Ok(())
        },
        &[

        ],
        &contract_invariants(),
        &["ContractCompleted"],
        args.to_json(),
        mutations,
        Vec::new(),
    )
}

impl CompleteArgs {
    pub fn to_json(&self) -> crate::kernel::Json {
        crate::kernel::Json::Object(vec![

        ])
    }
}

impl CompleteArgs {
    pub fn from_json(v: &crate::kernel::Json) -> Result<Self, crate::kernel::Refusal> {
let unknown = v.unknown_keys(&["id", "contract", "number"]);
if !unknown.is_empty() {
    return Err(crate::kernel::Refusal::UnknownArgument(format!(
        "Complete does not declare {} — it takes ",
        unknown.join(", ")
    )));
}
        Ok(Self {

        })
    }
}

