impl crate::kernel::Fielded for ReviseArgs {
    fn field(&self, name: &str) -> Option<crate::kernel::Field<'_>> {
        use crate::kernel::Field;
        use crate::kernel::Value;
        match name {
            "sequence" => Some(Field::Value(Value::Int(self.sequence))),
            "summary" => Some(Field::Value(Value::Str(self.summary.clone()))),
            _ => None,
        }
    }
}


#[derive(Debug, Clone)]
pub struct ReviseArgs {
    pub sequence: i64,
    pub summary: String,
}

pub fn dispatch_revise(
    repo: &mut impl crate::kernel::Repository<Contract>, id: &str, args: ReviseArgs, mutations: &mut Vec<crate::kernel::MutationRecord>,
) -> crate::kernel::DispatchResult<Contract> {


    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Revise",
        "Embryonaut::Contract",
        "Contract",
        "number.value",
        &args,
        &[

        ],
        None,
        |record| {
        record.revisions.push(Revision { sequence: args.sequence.clone(), summary: args.summary.clone() });
            Ok(())
        },
        &[

        ],
        &contract_invariants(),
        &["ContractRevised"],
        args.to_json(),
        mutations,
        Vec::new(),
    )
}

impl ReviseArgs {
    pub fn to_json(&self) -> crate::kernel::Json {
        crate::kernel::Json::Object(vec![
        ("sequence".to_string(), crate::kernel::Json::int(self.sequence)),
        ("summary".to_string(), crate::kernel::Json::Str(self.summary.clone())),
        ])
    }
}

impl ReviseArgs {
    pub fn from_json(v: &crate::kernel::Json) -> Result<Self, crate::kernel::Refusal> {
let unknown = v.unknown_keys(&["sequence", "summary", "id", "contract", "number"]);
if !unknown.is_empty() {
    return Err(crate::kernel::Refusal::UnknownArgument(format!(
        "Revise does not declare {} — it takes sequence, summary",
        unknown.join(", ")
    )));
}
        Ok(Self {
        sequence: { let x = v.require("sequence", "ReviseArgs")?; x.as_i64().ok_or_else(|| crate::kernel::Refusal::TypeMismatch(format!("ReviseArgs.sequence expects Integer, got {}", x.inspect())))? },
        summary: { let x = v.require("summary", "ReviseArgs")?; x.as_str().map(|s| s.to_string()).ok_or_else(|| crate::kernel::Refusal::TypeMismatch("ReviseArgs.summary: expected String".to_string()))? },
        })
    }
}


fn contract_invariants() -> crate::kernel::InvariantSet {
    crate::kernel::InvariantSet { aggregate: vec![], entities: vec![] }
}
